DROP TABLE IF EXISTS person_discounts;

CREATE TABLE person_discounts (
  id bigint PRIMARY KEY,
  person_id bigint,
  pizzeria_id bigint,
  discount numeric,
  CONSTRAINT fk_person_discounts_person_id FOREIGN KEY (person_id) REFERENCES person(id),
  CONSTRAINT fk_person_discounts_pizzeria_id FOREIGN KEY (pizzeria_id) REFERENCES pizzeria(id)
);

SELECT * FROM person_discounts;

DROP INDEX IF EXISTS idx_person_discounts_unique;

CREATE UNIQUE INDEX idx_person_discounts_unique ON person_discounts (person_id, pizzeria_id);

SET enable_seqscan = OFF;

EXPLAIN ANALYZE
SELECT *
FROM person_discounts
WHERE person_id = 1 AND pizzeria_id = 2;

ALTER TABLE person_discounts DROP CONSTRAINT IF EXISTS ch_nn_person_id;
ALTER TABLE person_discounts DROP CONSTRAINT IF EXISTS ch_nn_pizzeria_id;
ALTER TABLE person_discounts DROP CONSTRAINT IF EXISTS ch_nn_discount;
ALTER TABLE person_discounts DROP CONSTRAINT IF EXISTS ch_range_discount;
ALTER TABLE person_discounts ALTER COLUMN discount DROP DEFAULT;

ALTER TABLE person_discounts ADD CONSTRAINT ch_nn_person_id CHECK (person_id IS NOT NULL);
ALTER TABLE person_discounts ADD CONSTRAINT ch_nn_pizzeria_id CHECK (pizzeria_id IS NOT NULL);
ALTER TABLE person_discounts ADD CONSTRAINT ch_nn_discount CHECK (discount IS NOT NULL);

ALTER TABLE person_discounts ALTER COLUMN discount SET DEFAULT 0;

ALTER TABLE person_discounts ADD CONSTRAINT ch_range_discount CHECK (discount BETWEEN 0 AND 100);

COMMENT ON TABLE person_discounts IS
'Table storing personal discount rates for each person in each pizzeria';

COMMENT ON COLUMN person_discounts.id IS
'Primary key of the table';

COMMENT ON COLUMN person_discounts.person_id IS
'Reference to the person who receives the discount';

COMMENT ON COLUMN person_discounts.pizzeria_id IS
'Reference to the pizzeria where the discount is applied';

COMMENT ON COLUMN person_discounts.discount IS
'Discount percentage for a person in a specific pizzeria';

SELECT c.column_name,
       col_description('person_discounts'::regclass, c.ordinal_position) AS comment
FROM information_schema.columns c
WHERE c.table_name = 'person_discounts';

ALTER TABLE person_discounts ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS seq_person_discounts;

CREATE SEQUENCE seq_person_discounts START 1;

ALTER TABLE person_discounts
ALTER COLUMN id SET DEFAULT nextval('seq_person_discounts');

SELECT setval(
  'seq_person_discounts',
  (SELECT COUNT(*) + 1 FROM person_discounts)
);
